  local previous=Three.match(input,comp,atlas)or Special.match(input,comp,atlas)
  local p={};for k,v in pairs(previous or{})do p[k]=v end
  p.name='sevii-purple-native-'..s.id;p.wallRows=1;p.partialFacadePixels=3;p.nativeRowHeight=true;p.flatRoof=false;p.topArtVerified=true
  p.nativeSeviiFallback=previous
  p.nativeSeviiPurple={roof=roof,walls=walls[s.back],ridge=45.332865452560171,ridgeZ=32,wallTop=21,sourceHeaderTop=19,x=s.x,z=s.z,bodyBack=s.back,legacyWallHeight=s.legacyWallHeight}
